-- Explicações por artigo — Lei 12.850/2013 (Organizações Criminosas). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo 1º diz do que a lei trata e, principalmente, define o que é organização criminosa. Em linguagem simples: não basta um grupo qualquer. É preciso um grupo de 4 ou mais pessoas, com estrutura e divisão de tarefas (mesmo que informal), que busca vantagem de qualquer tipo praticando crimes graves (pena máxima acima de 4 anos) ou crimes de caráter transnacional. O §2º amplia o alcance da lei para crimes previstos em tratados internacionais e para organizações terroristas.', '["Quatro ou mais pessoas, estruturalmente ordenadas e com divisão de tarefas, ainda que de modo informal.","Objetivo: obter, direta ou indiretamente, vantagem de qualquer natureza (não é só dinheiro).","Meio: infrações penais com pena máxima superior a 4 anos OU de caráter transnacional.","A lei também trata da investigação, dos meios de obtenção de prova, de crimes correlatos e do procedimento (caput)."]'::jsonb, '["Troca clássica: ''três pessoas'' (isso é associação criminosa do art. 288 do Código Penal, não organização criminosa).","A pena ''superior a 4 anos'' é a pena MÁXIMA em abstrato de cada infração, não a pena mínima.","A vantagem não precisa ser patrimonial: ''de qualquer natureza''."]'::jsonb, 'Cinco pessoas se organizam: uma recebe as encomendas, outra faz o transporte, outra lava o dinheiro e uma comanda. Não há contrato nem hierarquia escrita, mas há estrutura e divisão de tarefas para praticar crimes com pena máxima superior a 4 anos. Isso se enquadra no conceito do §1º.', '["Assertiva que exige ''estrutura formal e hierarquia escrita'' erra: a lei admite divisão de tarefas informal.","Assertiva que fala em ''três ou mais pessoas'' para organização criminosa troca o número: são quatro."]'::jsonb, '[{"termo":"Transnacional","significado":"Crime cuja execução ou resultado ultrapassa as fronteiras do país."},{"termo":"Estruturalmente ordenada","significado":"Organizada, com papéis e ordem interna, ainda que sem formalidade."}]'::jsonb, '["Art. 288 (associação criminosa, 3 ou mais pessoas)","Art. 2º (crime de integrar organização criminosa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo 2º cria o crime de promover, constituir, financiar ou integrar organização criminosa, com pena de reclusão de 3 a 8 anos e multa, sem prejuízo das penas dos outros crimes praticados (concurso). Os parágrafos tratam de quem atrapalha a investigação, de causas de aumento e agravamento de pena (arma de fogo, comando, participação de criança, funcionário público, conexão com o exterior etc.), do afastamento cautelar de servidor, da perda do cargo e de regras duras de cumprimento de pena para lideranças e condenados que mantêm o vínculo.', '["Condutas do caput: promover, constituir, financiar ou integrar, pessoalmente ou por interposta pessoa.","Pena: reclusão de 3 a 8 anos e multa, e ainda as penas dos demais crimes praticados.","§1º: pune também quem impede ou embaraça a investigação de crime que envolva organização criminosa, se o fato não for crime mais grave.","§2º: aumento de até a metade se houver emprego de arma de fogo.","§3º: pena agravada para quem exerce o comando, mesmo sem praticar atos de execução.","§4º: aumento de 1/6 a 2/3 em cinco situações (criança ou adolescente ou crimes do ECA; funcionário público; produto destinado ao exterior; conexão com outras organizações; transnacionalidade).","§5º: indícios de que funcionário integra a organização permitem afastamento cautelar sem perda da remuneração, se necessário à investigação ou instrução.","§6º: condenação com trânsito em julgado leva à perda do cargo, função, emprego ou mandato e à interdição por 8 anos após cumprida a pena (o texto traz a indicação ''Vide ADI 5567'').","§7º: indícios de participação de policial fazem a Corregedoria instaurar inquérito e comunicar o Ministério Público (também com a indicação ''Vide ADI 5567'').","§8º: lideranças de organizações armadas (ou com armas à disposição) iniciam a pena em estabelecimento de segurança máxima.","§9º: o condenado por integrar organização (ou por crime cometido por meio dela) não progride de regime nem obtém livramento condicional ou outros benefícios se houver elementos de que mantém o vínculo."]'::jsonb, '["Não confundir: aumento ''até a metade'' (arma de fogo, §2º) com aumento ''de 1/6 a 2/3'' (§4º).","O §3º agrava a pena do comandante mesmo que ele não execute pessoalmente os atos.","O afastamento do §5º é cautelar e SEM prejuízo da remuneração; a perda do cargo (§6º) só vem com condenação transitada em julgado.","Nos §§6º e 7º o texto oficial remete à ADI 5567: antes de memorizar a regra, confira no site do STF o que foi decidido.","A pena do crime de organização não afasta as penas dos outros crimes: elas se somam (''sem prejuízo'')."]'::jsonb, 'João financia o grupo e Maria comanda as ações de longe, sem nunca pegar em arma. Ambos respondem pelo art. 2º. Maria sofre agravamento pelo comando (§3º). Se o grupo usou arma de fogo, a pena aumenta até a metade (§2º). Se um servidor público participou valendo-se do cargo, aplica-se também o aumento do §4º, II.', '["Assertiva dizendo que o art. 2º só pune quem executa pessoalmente os crimes está errada: promover, constituir, financiar e integrar também são condutas típicas, inclusive por interposta pessoa.","Assertiva que troca ''afastamento cautelar sem prejuízo da remuneração'' por ''com suspensão do salário'' inverte o §5º."]'::jsonb, '[{"termo":"Interposta pessoa","significado":"Pessoa que age em nome de outra, o ''laranja'' ou intermediário."},{"termo":"Trânsito em julgado","significado":"Momento em que a decisão não admite mais recurso."}]'::jsonb, '["Art. 1º, §1º (conceito de organização criminosa)","Art. 288 (associação criminosa)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo 3º lista os meios de obtenção de prova permitidos em qualquer fase da persecução penal (investigação e processo): colaboração premiada, captação ambiental, ação controlada, acesso a registros e dados, interceptação, afastamento de sigilos, infiltração de policiais e cooperação entre órgãos. A lista não é fechada: vale ''sem prejuízo de outros já previstos em lei''. Os §§1º e 2º permitem dispensar licitação, com sigilo, para contratar tecnologia usada na captação ambiental e na interceptação.', '["Em qualquer fase da persecução penal: tanto no inquérito quanto no processo.","Oito meios: colaboração premiada; captação ambiental; ação controlada; acesso a registros telefônicos/telemáticos, cadastrais, eleitorais e comerciais; interceptação; afastamento de sigilo financeiro, bancário e fiscal; infiltração; cooperação entre instituições.","Interceptação e afastamento de sigilos seguem a legislação específica.","A infiltração segue o art. 11 (como o próprio inciso indica).","§§1º e 2º: dispensa de licitação, havendo necessidade justificada de sigilo, para serviços e equipamentos de rastreamento (incisos II e V), com comunicação ao controle interno."]'::jsonb, '["São meios de obtenção de PROVA (instrumentos para chegar à prova), não a prova em si.","O rol é exemplificativo (''sem prejuízo de outros já previstos em lei'').","A dispensa de licitação do §1º vale só para os meios dos incisos II (captação ambiental) e V (interceptação)."]'::jsonb, 'A polícia investiga um grupo e usa, ao mesmo tempo, interceptação telefônica autorizada pelo juiz e cooperação com a polícia de outro estado para trocar informações. Ambos estão no rol do art. 3º.', '["Assertiva afirmando que o rol do art. 3º é taxativo erra: a lei ressalva outros meios previstos em lei.","Assertiva que diz que esses meios só podem ser usados após o início da ação penal erra: valem em qualquer fase da persecução."]'::jsonb, '[{"termo":"Persecução penal","significado":"Todo o caminho da apuração e punição: investigação mais processo."},{"termo":"Meio de obtenção de prova","significado":"Instrumento usado para encontrar ou conseguir a prova (diferente da prova em si)."}]'::jsonb, '["Art. 11 (infiltração)","Arts. 3º-A a 7º (colaboração premiada)","Arts. 8º e 9º (ação controlada)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define a natureza jurídica da colaboração premiada: é, ao mesmo tempo, um negócio jurídico processual (um acordo entre as partes) e um meio de obtenção de prova. Ela pressupõe utilidade e interesse públicos, isto é, só faz sentido quando traz resultado útil para a investigação e para a coletividade.', '["Dupla natureza: negócio jurídico processual + meio de obtenção de prova.","Pressupostos: utilidade e interesse públicos."]'::jsonb, '["A colaboração é meio de obtenção de prova; as declarações do colaborador, sozinhas, não bastam para decisões graves (veja o art. 4º, §16)."]'::jsonb, 'O investigado e o Ministério Público firmam acordo: ele revela a estrutura do grupo em troca de benefícios. O acordo é negócio processual; o que ele entrega serve para a investigação encontrar provas.', '["Assertiva que classifica a colaboração premiada como ''prova'' e não como meio de obtenção de prova contraria o art. 3º-A."]'::jsonb, '[{"termo":"Negócio jurídico processual","significado":"Acordo entre as partes que organiza como o processo vai andar."}]'::jsonb, '["Art. 3º, I","Art. 4º (benefícios e requisitos)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-3-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata do início das negociações do acordo. Receber a proposta marca o começo das tratativas e o ''marco de confidencialidade'': divulgar essas conversas antes do levantamento do sigilo pelo juiz viola o sigilo e a boa-fé. A proposta pode ser indeferida de forma sumária (com justificativa). Se não for indeferida, as partes assinam um Termo de Confidencialidade, que vincula os órgãos e impede o indeferimento posterior sem justa causa. Se o acordo não for celebrado por iniciativa de quem celebraria, ele não pode usar as informações ou provas que o colaborador entregou de boa-fé para outra finalidade.', '["O recebimento da proposta inicia as negociações e cria o marco de confidencialidade.","§1º: indeferimento sumário possível, com justificativa e ciência do interessado.","§2º: sem indeferimento sumário, assina-se o Termo de Confidencialidade, que vincula os órgãos e impede indeferimento posterior sem justa causa.","§3º: nem a proposta em análise nem o termo suspendem a investigação por si sós (salvo acordo em contrário sobre medidas cautelares e assecuratórias).","§4º: o acordo pode ser precedido de instrução para esclarecer objeto, fatos, definição jurídica, relevância, utilidade e interesse público.","§5º: os termos de recebimento e de confidencialidade são elaborados pelo celebrante e assinados por ele, pelo colaborador e pelo advogado ou defensor público com poderes específicos.","§6º: se o acordo não for celebrado por iniciativa do celebrante, ele não pode se valer das informações ou provas apresentadas de boa-fé pelo colaborador para outra finalidade."]'::jsonb, '["Negociar a proposta NÃO suspende automaticamente a investigação (§3º).","O Termo de Confidencialidade impede indeferimento posterior SEM JUSTA CAUSA (não impede qualquer indeferimento).","O §6º protege o colaborador de boa-fé: o que ele entregou não pode ser usado para outros fins se o celebrante desistir."]'::jsonb, 'O investigado entrega a proposta ao delegado. Se for aceita para análise, assinam o Termo de Confidencialidade. Se o delegado desistir depois, não pode usar contra o investigado o que ele revelou de boa-fé durante as tratativas.', '["Assertiva dizendo que a análise da proposta suspende a investigação inverte o §3º.","Assertiva que permite ao celebrante usar as informações do colaborador quando desiste do acordo contraria o §6º."]'::jsonb, '[{"termo":"Celebrante","significado":"Quem firma o acordo em nome do Estado (Ministério Público ou delegado de polícia)."},{"termo":"Medidas assecuratórias","significado":"Medidas para garantir bens ou resultados do processo, como o sequestro de bens."}]'::jsonb, '["Art. 3º-C (requisitos da proposta)","Art. 6º (termo do acordo)","Art. 7º (sigilo)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-3-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fixa como a proposta deve ser apresentada e a garantia de defesa técnica. A proposta precisa de procuração com poderes específicos ou de assinatura pessoal da parte e do advogado/defensor. Nenhuma negociação ocorre sem advogado constituído ou defensor público. O colaborador deve narrar todos os fatos ilícitos de que participou que tenham relação direta com os fatos investigados, e a defesa deve instruir a proposta com fatos descritos, provas e elementos de corroboração.', '["Proposta instruída com procuração de poderes específicos ou firmada pessoalmente pela parte e seu advogado/defensor.","§1º: nenhuma tratativa sem advogado constituído ou defensor público.","§2º: havendo conflito de interesses ou colaborador hipossuficiente, o celebrante solicita outro advogado ou defensor público.","§3º: o colaborador narra todos os fatos ilícitos de que participou e que tenham relação direta com os fatos investigados.","§4º: cabe à defesa instruir proposta e anexos, com fatos, circunstâncias, provas e elementos de corroboração."]'::jsonb, '["É proibida qualquer tratativa sem advogado ou defensor público (§1º).","O dever de narrar é sobre fatos com RELAÇÃO DIRETA com os investigados, mas deve ser completo quanto a esses fatos."]'::jsonb, 'O investigado chega sozinho à delegacia propondo um acordo. As conversas não podem prosseguir até que haja advogado constituído ou defensor público presente.', '["Assertiva que admite iniciar tratativas sem defensor, para depois nomeá-lo, contraria o §1º."]'::jsonb, '[{"termo":"Hipossuficiente","significado":"Quem não tem condições econômicas ou técnicas de se defender sozinho."},{"termo":"Elementos de corroboração","significado":"Indícios e provas que confirmam o que o colaborador afirma."}]'::jsonb, '["Art. 3º-B (início das negociações)","Art. 4º, §15 (assistência obrigatória por defensor)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-3-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É o artigo central da colaboração premiada. Diz quais benefícios o juiz pode conceder (perdão judicial, redução de até 2/3 da pena privativa de liberdade ou substituição por restritiva de direitos) e exige que a colaboração seja efetiva e voluntária e traga ao menos um dos cinco resultados listados (identificar coautores, revelar a estrutura, prevenir infrações, recuperar o produto do crime, localizar a vítima). Os parágrafos organizam todo o procedimento: quem negocia, como o juiz homologa, o que é nulo, quando o acordo pode ser retratado ou rescindido e o limite probatório do §16.', '["Benefícios do caput: perdão judicial, redução de até 2/3 da pena privativa de liberdade ou substituição por restritiva de direitos.","Resultados possíveis (basta um ou mais): identificar coautores e partícipes; revelar estrutura hierárquica e divisão de tarefas; prevenir infrações; recuperar produto ou proveito do crime (total ou parcial); localizar vítima com integridade física preservada.","§1º: na concessão considera-se personalidade do colaborador, natureza, circunstâncias, gravidade e repercussão do fato e eficácia da colaboração.","§2º: perdão judicial pode ser requerido ou representado a qualquer tempo, mesmo sem previsão na proposta inicial.","§3º: prazo para denúncia ou o processo, quanto ao colaborador, pode ser suspenso por até 6 meses, prorrogáveis por igual período, suspendendo-se o prazo prescricional.","§4º e §4º-A: o Ministério Público pode deixar de oferecer denúncia se o colaborador não for o líder e for o primeiro a colaborar sobre fato de que não havia conhecimento prévio; há conhecimento prévio quando já existe inquérito ou procedimento investigatório sobre os fatos.","§5º: colaboração posterior à sentença: pena reduzida até a metade ou progressão de regime ainda que ausentes os requisitos objetivos.","§6º: o juiz NÃO participa das negociações do acordo.","§7º: o juiz ouve o colaborador sigilosamente, com o defensor, e analisa regularidade e legalidade, adequação dos benefícios, adequação dos resultados e voluntariedade na homologação.","§7º-A e §7º-B: análise fundamentada do mérito antes de conceder os benefícios (salvo as exceções do texto); nulas as cláusulas de renúncia ao direito de impugnar a decisão homologatória.","§8º: o juiz pode recusar a homologação, devolvendo às partes para adequações.","§9º a §13: depois de homologado, o colaborador pode ser ouvido (sempre com defensor); retratação da proposta impede uso das provas autoincriminatórias exclusivamente contra ele; réu delatado manifesta-se por último (§10-A); a sentença aprecia os termos e a eficácia do acordo; registro das tratativas por gravação.","§14: o colaborador renuncia ao direito ao silêncio e se compromete a dizer a verdade (o texto traz ''Vide ADI 5567'').","§15: o colaborador deve estar assistido por defensor em todos os atos.","§16: nenhuma destas medidas pode ser decretada ou proferida com base APENAS nas declarações do colaborador: medidas cautelares reais ou pessoais, recebimento de denúncia ou queixa-crime e sentença condenatória.","§17 e §18: o acordo pode ser rescindido por omissão dolosa e pressupõe que o colaborador cesse o envolvimento em conduta ilícita ligada ao objeto da colaboração."]'::jsonb, '["O §16 é o mais cobrado: declarações do colaborador sozinhas NÃO bastam para cautelares, recebimento da denúncia nem condenação.","O juiz não negocia (§6º), mas homologa (§7º): analisa regularidade, legalidade, benefícios, resultados e voluntariedade.","Redução ''até 2/3'' (caput) é diferente da redução ''até a metade'' quando a colaboração é posterior à sentença (§5º).","Não denunciar (§4º) exige: não ser o líder E ser o primeiro a colaborar, sobre fato de que não havia conhecimento prévio.","Cláusulas que renunciam ao direito de impugnar a homologação são nulas (§7º-B).","O réu delatado fala por último (§10-A)."]'::jsonb, 'Pedro, integrante (não líder), é o primeiro a procurar o Ministério Público e revela uma ação criminosa ainda desconhecida. O MP pode até deixar de denunciá-lo (§4º). Se, em vez disso, firmar acordo para reduzir a pena, o juiz homologa depois de ouvir Pedro sigilosamente com o defensor. Ainda assim, a denúncia contra os outros não pode ser recebida só com a palavra de Pedro (§16): é preciso corroboração.', '["Assertiva dizendo que o juiz participa da negociação do acordo erra: o §6º veda.","Assertiva que permite condenar alguém apenas com a delação contraria o §16, III.","Assertiva que atribui ao colaborador a manutenção do direito ao silêncio nos depoimentos erra: o §14 diz que ele renuncia a esse direito (confira também a ADI indicada no texto)."]'::jsonb, '[{"termo":"Homologação","significado":"Aprovação do juiz após conferir legalidade, regularidade e voluntariedade."},{"termo":"Perdão judicial","significado":"Dispensa de pena concedida pelo juiz."},{"termo":"Retratação","significado":"Desistência da proposta por qualquer das partes."}]'::jsonb, '["Art. 3º-A a 3º-C","Arts. 5º a 7º","Art. 33 do Código Penal (regime inicial) citado no §7º, II"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lista os direitos do colaborador, ligados à proteção e à preservação de sua identidade: medidas de proteção previstas em lei específica, preservação de nome, qualificação, imagem e informações pessoais, condução em juízo separada dos demais, audiências sem contato visual com outros acusados, sigilo perante a imprensa (sem foto ou filmagem sem autorização escrita) e cumprimento de pena ou prisão cautelar em estabelecimento diverso dos demais corréus ou condenados.', '["I – medidas de proteção da legislação específica.","II – nome, qualificação, imagem e demais informações pessoais preservados.","III – ser conduzido em juízo separadamente dos demais coautores e partícipes.","IV – participar das audiências sem contato visual com os outros acusados.","V – identidade não revelada pela imprensa nem foto/filmagem sem prévia autorização por escrito.","VI – cumprir pena ou prisão cautelar em estabelecimento diverso dos demais corréus ou condenados."]'::jsonb, '["A autorização para divulgar imagem ou identidade precisa ser PRÉVIA e POR ESCRITO.","O direito do inciso VI vale tanto para a pena quanto para a prisão cautelar."]'::jsonb, 'Em audiência, o colaborador depõe sem ver os demais acusados e, preso, cumpre a medida em unidade separada dos corréus. São direitos dos incisos IV e VI.', '["Assertiva que permite à imprensa divulgar a imagem do colaborador se ele não se opuser erra: precisa de autorização prévia por escrito."]'::jsonb, '[{"termo":"Corréu","significado":"Outro acusado no mesmo processo."}]'::jsonb, '["Art. 18 (crime de revelar identidade do colaborador)","Art. 6º, V (medidas de proteção no termo do acordo)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fixa o conteúdo mínimo do termo de acordo da colaboração premiada. Ele deve ser escrito e trazer: o relato da colaboração e seus possíveis resultados, as condições da proposta do Ministério Público ou do delegado, a declaração de aceitação do colaborador e do defensor, as assinaturas do representante do MP ou do delegado, do colaborador e do defensor, e, quando necessário, a especificação das medidas de proteção ao colaborador e à família.', '["Forma: por escrito.","Conteúdo: relato e possíveis resultados; condições da proposta; aceitação do colaborador e do defensor; assinaturas; medidas de proteção, quando necessário."]'::jsonb, '["As assinaturas exigidas são do MP ou do delegado, do colaborador E do defensor.","As medidas de proteção só constam ''quando necessário''."]'::jsonb, 'O termo traz o relato do que o colaborador vai entregar, as condições oferecidas pelo MP, a aceitação dele e do advogado, as assinaturas e, se houver risco, as medidas para proteger a família.', '["Assertiva que dispensa a assinatura do defensor no termo contraria o inciso IV."]'::jsonb, '[{"termo":"Termo de acordo","significado":"Documento escrito que formaliza a colaboração premiada."}]'::jsonb, '["Art. 4º, §§6º e 7º (negociação e homologação)","Art. 5º (direitos do colaborador)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cuida do sigilo do acordo. O pedido de homologação é distribuído sigilosamente, com informações que não identifiquem o colaborador nem o objeto. Os detalhes vão direto ao juiz sorteado, que decide em 48 horas. O acesso aos autos é restrito ao juiz, ao Ministério Público e ao delegado, com acesso amplo do defensor aos elementos de defesa (precedido de autorização judicial), ressalvadas as diligências em andamento. O acordo e os depoimentos ficam em sigilo até o recebimento da denúncia ou queixa, e o juiz não pode decidir pela publicidade em nenhuma hipótese.', '["Distribuição sigilosa, sem dados que identifiquem colaborador e objeto.","§1º: informações detalhadas ao juiz da distribuição, que decide em 48 horas.","§2º: acesso restrito ao juiz, ao MP e ao delegado; defensor com amplo acesso aos elementos de defesa, com autorização judicial, salvo diligências em andamento.","§3º: sigilo do acordo e dos depoimentos até o recebimento da denúncia ou queixa-crime; magistrado não pode decidir por sua publicidade em hipótese alguma."]'::jsonb, '["O prazo de decisão sobre o pedido é de 48 horas.","O sigilo vai até o RECEBIMENTO da denúncia (não até o oferecimento).","O §3º veda ao juiz decidir pela publicidade ''em qualquer hipótese''."]'::jsonb, 'O MP pede a homologação. O pedido é distribuído sem identificar o colaborador e, em 48 horas, o juiz decide. O acordo só deixa de ser sigiloso quando a denúncia for recebida.', '["Assertiva que fixa prazo de 24 horas para o juiz decidir sobre a homologação troca o prazo: são 48 horas (as 24 horas aparecem na infiltração, art. 12, §1º).","Assertiva que permite ao juiz tornar o acordo público antes do recebimento da denúncia contraria o §3º."]'::jsonb, '[{"termo":"Distribuição","significado":"Sorteio do processo ou pedido para um juiz."}]'::jsonb, '["Art. 4º, §7º (homologação)","Art. 12, §1º (prazo de 24 horas na infiltração)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define a ação controlada: é retardar a intervenção policial ou administrativa sobre a ação de organização criminosa, mantendo-a sob observação e acompanhamento, para que a medida legal ocorra no momento mais eficaz à formação de provas e obtenção de informações. O retardamento é comunicado previamente ao juiz, que pode estabelecer limites e comunicar o MP. A comunicação é sigilosa; até o fim da diligência o acesso aos autos é restrito ao juiz, ao MP e ao delegado; ao final, elabora-se auto circunstanciado.', '["Conceito: retardar a intervenção policial ou administrativa, mantendo observação e acompanhamento, para agir no momento mais eficaz.","§1º: comunicação PRÉVIA ao juiz competente, que pode estabelecer limites e comunica o MP.","§2º: comunicação distribuída sigilosamente, sem dados que indiquem a operação.","§3º: acesso aos autos restrito ao juiz, ao MP e ao delegado até o encerramento da diligência.","§4º: ao término, elabora-se auto circunstanciado."]'::jsonb, '["A comunicação ao juiz é PRÉVIA (antes do retardamento), e não depois.","Não se pede ''autorização'' no texto do caput: o juiz é comunicado e pode fixar limites.","Não confundir com infiltração (agente que se passa por integrante): na ação controlada a polícia apenas adia a intervenção."]'::jsonb, 'A polícia sabe que um carregamento ilícito sairá do galpão. Em vez de prender já, comunica o juiz, acompanha o caminhão e age quando puder alcançar toda a rede.', '["Assertiva que diz que a ação controlada dispensa comunicação ao juiz erra: o §1º exige comunicação prévia.","Assertiva que confunde ação controlada com infiltração de agentes troca institutos distintos."]'::jsonb, '[{"termo":"Auto circunstanciado","significado":"Documento detalhado que descreve o que ocorreu na diligência."}]'::jsonb, '["Art. 9º (fronteiras)","Art. 3º, III"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata da ação controlada que envolve passagem pelas fronteiras: o retardamento da intervenção só pode ocorrer com a cooperação das autoridades dos países que sejam o provável itinerário ou destino do investigado. O objetivo é reduzir os riscos de fuga e de extravio do produto, objeto, instrumento ou proveito do crime.', '["Quando há transposição de fronteiras, é indispensável a cooperação das autoridades dos países do provável itinerário ou destino.","Finalidade: reduzir riscos de fuga e de extravio do produto, objeto, instrumento ou proveito do crime."]'::jsonb, '["Sem a cooperação dos países envolvidos, o retardamento NÃO pode ocorrer."]'::jsonb, 'Uma carga ilícita seguirá do Brasil para outro país. A polícia só pode adiar a apreensão se as autoridades do país de trânsito ou destino cooperarem.', '["Assertiva que dispensa a cooperação internacional na ação controlada transfronteiriça erra: o art. 9º a exige."]'::jsonb, '[{"termo":"Transposição de fronteiras","significado":"Passagem do investigado ou da carga de um país para outro."}]'::jsonb, '["Art. 8º (ação controlada)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regula a infiltração de agentes de polícia em tarefas de investigação. Exige representação do delegado ou requerimento do MP (após manifestação técnica do delegado quando solicitada no curso do inquérito) e uma autorização judicial circunstanciada, motivada e sigilosa, que fixa os limites. É admitida se houver indícios de infração do art. 1º e a prova não puder ser produzida por outros meios. O prazo é de até 6 meses, com renovações se comprovada a necessidade, e há relatório ao final e relatórios sob demanda.', '["Quem pede: delegado de polícia (representa) ou MP (requer, após manifestação técnica do delegado quando solicitada no curso de inquérito).","Autorização judicial circunstanciada, motivada e sigilosa, com limites estabelecidos.","§1º: se a iniciativa for do delegado, o juiz ouve antes o Ministério Público.","§2º: exige indícios de infração do art. 1º e prova que não possa ser produzida por outros meios (subsidiariedade).","§3º: prazo de até 6 meses, com renovações desde que comprovada a necessidade.","§4º: ao fim do prazo, relatório circunstanciado ao juiz, que cientifica o MP.","§5º: no inquérito, o delegado pode determinar aos agentes e o MP requisitar, a qualquer tempo, relatório da atividade."]'::jsonb, '["A infiltração é a última opção: só se a prova não puder ser obtida por outros meios (§2º).","Prazo de até 6 meses com renovações (na infiltração virtual do art. 10-A há teto total de 720 dias).","Depende de autorização judicial: não basta decisão do delegado ou do MP."]'::jsonb, 'O delegado representa pela infiltração de um agente na quadrilha porque as outras provas não são possíveis. O juiz ouve o MP e autoriza por até 6 meses, com limites. Ao final, o relatório circunstanciado chega ao juiz.', '["Assertiva dizendo que a infiltração dispensa autorização judicial erra: o art. 10 exige.","Assertiva que fixa o prazo máximo em 6 meses, sem possibilidade de renovação, contraria o §3º."]'::jsonb, '[{"termo":"Infiltração","significado":"Agente de polícia que se insere na organização para colher informações, sob autorização judicial."},{"termo":"Subsidiariedade","significado":"Medida usada só quando outros meios disponíveis não resolvem."}]'::jsonb, '["Art. 1º (infrações abrangidas)","Arts. 10-A a 14","Art. 3º, VII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Autoriza o agente infiltrado virtual: policiais infiltrados na internet para investigar crimes desta lei e conexos praticados por organizações criminosas, obedecidos os requisitos do art. 10, com demonstração da necessidade, indicação do alcance das tarefas e dos nomes ou apelidos dos investigados e, quando possível, dos dados de conexão ou cadastrais. O prazo é de até 6 meses, renovável, com limite total de 720 dias, e a prova obtida sem observar o artigo é nula.', '["Pode atuar na internet para investigar crimes desta lei e conexos praticados por organizações criminosas.","Requisitos do caput do art. 10, mais necessidade, alcance das tarefas, nomes ou apelidos dos investigados e, quando possível, dados de conexão ou cadastrais.","§1º: dados de conexão (hora, data, início, término, duração, IP e terminal de origem) e dados cadastrais (nome e endereço do assinante ou usuário).","§2º: se a iniciativa for do delegado, o juiz ouve o MP antes de decidir.","§3º: exige indícios de infração do art. 1º e que as provas não possam ser produzidas por outros meios.","§4º: até 6 meses, com renovações, ordem judicial fundamentada, total máximo de 720 dias.","§5º: ao final, relatório e todos os atos eletrônicos registrados, gravados, armazenados e apresentados ao juiz, que cientifica o MP.","§6º: relatório pode ser requisitado a qualquer tempo, inclusive pelo juiz.","§7º: é nula a prova obtida sem a observância do artigo."]'::jsonb, '["Limite de 720 dias no total: só aparece na infiltração VIRTUAL.","Ao final da operação, TODOS os atos eletrônicos devem ser registrados e entregues ao juiz.","§7º: prova obtida sem observar o artigo é NULA."]'::jsonb, 'Um policial cria identidade virtual para entrar em um grupo online de uma organização criminosa. Com ordem judicial fundamentada, atua por até 6 meses, renovável até o total de 720 dias, e entrega ao juiz o relatório e todos os registros eletrônicos.', '["Assertiva que dispensa o limite de 720 dias na infiltração virtual erra: o §4º o impõe.","Assertiva que valida prova obtida em infiltração virtual sem ordem judicial contraria o §7º (nulidade)."]'::jsonb, '[{"termo":"Dados de conexão","significado":"Informações técnicas da conexão: data, hora, duração, IP e terminal de origem."},{"termo":"Dados cadastrais","significado":"Nome e endereço de quem é o assinante ou usuário da conexão."}]'::jsonb, '["Art. 10 (requisitos gerais)","Art. 10-B a 10-D","Art. 1º (crimes abrangidos)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-10-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Garante o sigilo da infiltração: as informações vão diretamente ao juiz que autorizou a medida, que zela pelo sigilo. Antes da conclusão da operação, o acesso aos autos é reservado ao juiz, ao Ministério Público e ao delegado responsável pela operação, para proteger as investigações.', '["Informações encaminhadas diretamente ao juiz que autorizou a medida, responsável por zelar pelo sigilo.","Antes da conclusão da operação: acesso apenas do juiz, do MP e do delegado responsável."]'::jsonb, '["Quem acessa os autos antes da conclusão é um grupo fechado de três: juiz, MP e delegado responsável."]'::jsonb, 'Durante a operação, nem a defesa dos investigados tem acesso aos autos da infiltração: só o juiz, o MP e o delegado responsável.', '["Assertiva que franqueia a qualquer investigado o acesso aos autos antes da conclusão da operação contraria o parágrafo único."]'::jsonb, '[]'::jsonb, '["Art. 12 (sigilo do pedido de infiltração)","Art. 10-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-10-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Protege o policial que oculta sua identidade na internet para colher indícios de autoria e materialidade dos crimes do art. 1º: ele não comete crime por isso. Mas há um limite: se deixar de observar a estrita finalidade da investigação, responde pelos excessos praticados.', '["Não comete crime o policial que oculta sua identidade pela internet para colher indícios de autoria e materialidade dos crimes do art. 1º.","Parágrafo único: quem não observa a estrita finalidade da investigação responde pelos excessos."]'::jsonb, '["A proteção cobre a ocultação de identidade para a finalidade da investigação; os excessos são punidos."]'::jsonb, 'O agente usa um perfil falso para entrar em um grupo criminoso online e registrar as conversas. Isso não é crime. Se ele induzisse outros a cometer delitos fora da finalidade da investigação, responderia pelo excesso.', '["Assertiva que isenta o agente de qualquer responsabilidade, mesmo por excessos, contraria o parágrafo único."]'::jsonb, '[{"termo":"Autoria e materialidade","significado":"Quem praticou o crime (autoria) e a prova de que ele ocorreu (materialidade)."}]'::jsonb, '["Art. 10-A","Art. 13 (excessos)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-10-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao concluir a investigação por infiltração virtual, todos os atos eletrônicos praticados devem ser registrados, gravados, armazenados e encaminhados ao juiz e ao Ministério Público, com relatório circunstanciado. Eles são reunidos em autos apartados e apensados ao processo criminal e ao inquérito, preservando a identidade do agente e a intimidade dos envolvidos.', '["Todos os atos eletrônicos registrados, gravados, armazenados e enviados ao juiz e ao MP, com relatório circunstanciado.","Reunidos em autos apartados e apensados ao processo criminal e ao inquérito.","Preservam-se a identidade do agente e a intimidade dos envolvidos."]'::jsonb, '["Os registros ficam em autos APARTADOS, para proteger o agente e os envolvidos."]'::jsonb, 'Terminada a operação virtual, o delegado entrega ao juiz e ao MP o relatório e todo o material eletrônico. Esse material forma autos apartados ligados ao processo, sem expor a identidade do agente.', '["Assertiva que permite descartar parte dos registros eletrônicos da operação contraria o dever de registrar e encaminhar todos os atos."]'::jsonb, '[{"termo":"Autos apartados","significado":"Conjunto de documentos separado do processo principal, mas ligado a ele."}]'::jsonb, '["Art. 10-A, §5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-10-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Diz o que o pedido de infiltração (requerimento do MP ou representação do delegado) deve conter: a demonstração da necessidade da medida, o alcance das tarefas dos agentes e, quando possível, os nomes ou apelidos dos investigados e o local da infiltração. O parágrafo único permite que órgãos de registro e cadastro público incluam, em procedimento sigiloso e mediante requisição judicial, as informações necessárias à identidade fictícia criada na infiltração pela internet.', '["Conteúdo do pedido: necessidade, alcance das tarefas, nomes ou apelidos dos investigados e local, quando possível.","Parágrafo único: órgãos de registro e cadastro público podem incluir informações da identidade fictícia (infiltração na internet), em procedimento sigiloso, mediante requisição judicial."]'::jsonb, '["Nomes, apelidos e local só são exigidos ''quando possível''; necessidade e alcance das tarefas são sempre necessários."]'::jsonb, 'O delegado representa pela infiltração apontando por que a medida é necessária, o que o agente poderá fazer e, quando possível, quem e onde investigar.', '["Assertiva que dispensa a demonstração da necessidade da medida no pedido erra: o art. 11 a exige."]'::jsonb, '[{"termo":"Identidade fictícia","significado":"Identidade criada para proteger o agente e permitir a infiltração."}]'::jsonb, '["Art. 10","Art. 10-A","Art. 3º, VII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata do sigilo e do prazo de decisão do pedido de infiltração. O pedido é distribuído sigilosamente, sem informações que indiquem a operação ou identifiquem o agente. As informações vão diretamente ao juiz competente, que decide em 24 horas, após manifestação do MP quando a iniciativa for do delegado. Os autos acompanham a denúncia e são disponibilizados à defesa, preservada a identidade do agente. Se houver indícios seguros de risco iminente ao agente, a operação é sustada.', '["Distribuição sigilosa, sem dados que indiquem a operação ou identifiquem o agente.","§1º: juiz decide em 24 horas, após manifestação do MP na representação do delegado; devem ser adotadas medidas para o êxito da investigação e a segurança do agente.","§2º: autos acompanham a denúncia e são disponibilizados à defesa, preservada a identidade do agente.","§3º: com indícios seguros de risco iminente ao agente, a operação é sustada por requisição do MP ou pelo delegado, com imediata ciência ao MP e ao juiz."]'::jsonb, '["Prazo de decisão aqui: 24 horas (na homologação da colaboração, art. 7º, §1º, são 48 horas).","Os autos chegam à defesa junto com a denúncia, mas sem revelar a identidade do agente."]'::jsonb, 'O delegado representa pela infiltração. Em 24 horas, após ouvir o MP, o juiz decide. Se o agente passar a correr risco iminente, a operação é sustada.', '["Assertiva que fixa 48 horas para o juiz decidir sobre a infiltração troca o prazo: são 24 horas."]'::jsonb, '[{"termo":"Sustar","significado":"Interromper a operação."}]'::jsonb, '["Art. 7º, §1º (48 horas na homologação)","Art. 10 (autorização)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Responsabilidade do agente infiltrado. Se ele não guardar, na atuação, a proporcionalidade com a finalidade da investigação, responde pelos excessos. Porém, não é punível a prática de crime pelo agente infiltrado no curso da investigação quando for inexigível conduta diversa.', '["Caput: o agente que não observa a proporcionalidade com a finalidade da investigação responde pelos excessos.","Parágrafo único: não é punível o crime praticado pelo agente infiltrado no curso da investigação quando inexigível conduta diversa."]'::jsonb, '["Duas ideias que convivem: respondem-se os excessos, mas não se pune o crime cometido quando não se podia exigir outra conduta.","A inexigibilidade de conduta diversa é a base da não punição (causa de exclusão da culpabilidade)."]'::jsonb, 'Para não ser descoberto, o agente participa de um ato menor do grupo, sem alternativa razoável: não é punido. Se exagera e pratica crime desproporcional à investigação, responde pelo excesso.', '["Assertiva que isenta totalmente o agente de qualquer responsabilidade por seus atos na infiltração contraria o caput."]'::jsonb, '[{"termo":"Proporcionalidade","significado":"Adequação entre o que se faz e o objetivo da investigação."},{"termo":"Inexigibilidade de conduta diversa","significado":"Situação em que não se podia exigir outro comportamento da pessoa."}]'::jsonb, '["Art. 10-C, parágrafo único"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lista os direitos do agente infiltrado: recusar ou fazer cessar a atuação infiltrada; ter a identidade alterada (aplicando-se, no que couber, o art. 9º da Lei 9.807/1999) e usufruir das medidas de proteção a testemunhas; ter nome, qualificação, imagem, voz e informações pessoais preservados durante a investigação e o processo, salvo decisão judicial em contrário; e não ter a identidade revelada nem ser fotografado ou filmado pela imprensa sem autorização prévia por escrito.', '["I – recusar ou fazer cessar a atuação infiltrada.","II – identidade alterada e medidas de proteção a testemunhas.","III – nome, qualificação, imagem, voz e informações pessoais preservados, salvo decisão judicial.","IV – identidade não revelada pela imprensa, sem fotografia ou filmagem sem autorização prévia por escrito."]'::jsonb, '["O agente pode RECUSAR ou fazer cessar a infiltração: não é obrigado a continuar.","A preservação de dados pessoais cede se houver decisão judicial em contrário (inciso III)."]'::jsonb, 'Sentindo-se em risco, o agente decide sair da operação e recebe nova identidade com proteção semelhante à de testemunhas.', '["Assertiva que obriga o agente a permanecer infiltrado até o fim da operação contraria o inciso I."]'::jsonb, '[]'::jsonb, '["Art. 5º (direitos do colaborador, rol semelhante)","Lei 9.807/1999, art. 9º (citada no inciso II)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O delegado de polícia e o Ministério Público podem acessar, SEM autorização judicial, apenas os dados cadastrais do investigado que informem exclusivamente a qualificação pessoal, a filiação e o endereço, mantidos pela Justiça Eleitoral, empresas telefônicas, instituições financeiras, provedores de internet e administradoras de cartão de crédito.', '["Quem acessa: delegado de polícia e Ministério Público.","Sem autorização judicial.","Só dados cadastrais que informem exclusivamente qualificação pessoal, filiação e endereço.","Fontes: Justiça Eleitoral, empresas telefônicas, instituições financeiras, provedores de internet e administradoras de cartão de crédito."]'::jsonb, '["Só os dados cadastrais básicos dispensam ordem judicial: conteúdo de comunicações e extratos exigem a legislação específica.","A expressão ''exclusivamente'' limita o acesso: qualificação, filiação e endereço."]'::jsonb, 'O delegado requisita à operadora o nome completo, a filiação e o endereço do titular de uma linha, sem ordem do juiz. Já para obter extratos bancários seria necessária a via judicial prevista em lei específica.', '["Assertiva que amplia o acesso sem ordem judicial a dados bancários completos erra: o art. 15 limita a qualificação, filiação e endereço."]'::jsonb, '[{"termo":"Dados cadastrais","significado":"Informações de identificação, como nome, filiação e endereço."}]'::jsonb, '["Art. 3º, IV e VI","Art. 21 (crime de recusar dados)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As empresas de transporte devem possibilitar, pelo prazo de 5 anos, acesso direto e permanente do juiz, do Ministério Público ou do delegado de polícia aos bancos de dados de reservas e registro de viagens.', '["Obrigadas: empresas de transporte.","Prazo: 5 anos.","Acesso direto e permanente do juiz, do MP ou do delegado de polícia aos bancos de reservas e registros de viagens."]'::jsonb, '["O prazo é de 5 anos (o mesmo prazo do art. 17, para telefonia)."]'::jsonb, 'O delegado consulta diretamente o banco de reservas de uma empresa de ônibus para rastrear as viagens de um investigado, sem esperar a resposta de um ofício.', '["Assertiva que fixa prazo de 2 anos para a guarda desses dados troca o prazo: são 5 anos."]'::jsonb, '[]'::jsonb, '["Art. 17 (telefonia, 5 anos)","Art. 15 (dados cadastrais)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As concessionárias de telefonia fixa ou móvel devem manter, pelo prazo de 5 anos, à disposição das autoridades do art. 15 (delegado e Ministério Público), os registros de identificação dos números dos terminais de origem e destino das ligações telefônicas internacionais, interurbanas e locais.', '["Obrigadas: concessionárias de telefonia fixa ou móvel.","Prazo de guarda: 5 anos.","Registros: números dos terminais de origem e de destino das ligações internacionais, interurbanas e locais."]'::jsonb, '["São registros de identificação dos números (origem e destino), não o conteúdo das conversas."]'::jsonb, 'A operadora mantém por 5 anos o histórico de quem ligou para quem. O delegado pode usar esse registro no inquérito.', '["Assertiva que inclui o conteúdo das conversas entre os registros guardados erra: o art. 17 trata dos números de origem e destino."]'::jsonb, '[]'::jsonb, '["Art. 15 (autoridades com acesso)","Art. 16 (transporte)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cria o crime de revelar a identidade, fotografar ou filmar o colaborador sem sua prévia autorização por escrito. A pena é de reclusão de 1 a 3 anos e multa.', '["Condutas: revelar a identidade, fotografar ou filmar o colaborador.","Condição: sem prévia autorização por escrito.","Pena: reclusão de 1 a 3 anos e multa."]'::jsonb, '["A autorização do colaborador deve ser prévia e por escrito."]'::jsonb, 'Um repórter divulga o rosto do colaborador sem que ele tenha autorizado por escrito. O repórter incide no art. 18.', '["Assertiva que torna lícita a divulgação com autorização apenas verbal erra: exige-se autorização por escrito."]'::jsonb, '[]'::jsonb, '["Art. 5º, II e V (direitos do colaborador)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime de falsa colaboração: imputar falsamente, a pretexto de colaborar com a Justiça, a prática de infração penal a pessoa que se sabe inocente, ou revelar informações sobre a estrutura da organização criminosa que se sabe inverídicas. A pena é de reclusão de 1 a 4 anos e multa.', '["Condutas: imputar falsamente infração penal a quem se sabe inocente; ou revelar informações inverídicas sobre a estrutura da organização.","Contexto: sob pretexto de colaboração com a Justiça.","Pena: reclusão de 1 a 4 anos e multa."]'::jsonb, '["É necessário saber que a pessoa é inocente ou que a informação é inverídica (conhecimento da falsidade)."]'::jsonb, 'Para obter benefícios, o colaborador aponta como líder uma pessoa que ele sabe ser inocente. Pratica o crime do art. 19.', '["Assertiva que pune o colaborador por erro de boa-fé em suas informações contraria a exigência de que ele saiba da falsidade."]'::jsonb, '[]'::jsonb, '["Art. 4º (colaboração premiada)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime de descumprir determinação de sigilo das investigações que envolvam a ação controlada e a infiltração de agentes. A pena é de reclusão de 1 a 4 anos e multa.', '["Conduta: descumprir determinação de sigilo das investigações de ação controlada e de infiltração.","Pena: reclusão de 1 a 4 anos e multa."]'::jsonb, '["O crime protege o sigilo de DUAS medidas: ação controlada e infiltração."]'::jsonb, 'Um servidor vaza a data da operação de ação controlada autorizada pelo juiz. Responde pelo art. 20.', '["Assertiva que estende o art. 20 ao sigilo da colaboração premiada em geral erra: o tipo menciona ação controlada e infiltração."]'::jsonb, '[]'::jsonb, '["Arts. 8º e 12 (sigilo na ação controlada e na infiltração)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime de recusar ou omitir dados cadastrais, registros, documentos e informações requisitadas pelo juiz, Ministério Público ou delegado de polícia, no curso de investigação ou do processo. A pena é de reclusão de 6 meses a 2 anos e multa. O parágrafo único pune quem, de forma indevida, se apossa, propala, divulga ou faz uso dos dados cadastrais de que trata a lei.', '["Conduta: recusar ou omitir dados, registros, documentos e informações requisitados pelo juiz, MP ou delegado.","Pena: reclusão de 6 meses a 2 anos e multa.","Parágrafo único: mesma pena para quem, indevidamente, se apossa, propala, divulga ou usa os dados cadastrais."]'::jsonb, '["A requisição precisa vir do juiz, do MP ou do delegado, no curso de investigação ou processo.","O parágrafo único protege os dados cadastrais contra uso indevido."]'::jsonb, 'A operadora recusa informar, sem justificativa, os dados cadastrais requisitados pelo delegado. A responsável responde pelo art. 21.', '["Assertiva que restringe a requisição apenas ao juiz erra: também o MP e o delegado podem requisitar."]'::jsonb, '[{"termo":"Propalar","significado":"Espalhar, divulgar para muitas pessoas."}]'::jsonb, '["Art. 15 (acesso a dados cadastrais)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime de obstrução de ações contra o crime organizado: solicitar, mediante promessa ou concessão de vantagem, ou ordenar a prática de violência ou grave ameaça contra agente público, advogado, defensor dativo, jurado, testemunha, colaborador ou perito, para impedir, embaraçar ou retaliar o andamento de processo ou investigação de crimes de organização criminosa ou a aprovação de medida contra o crime organizado. A pena é de reclusão de 4 a 12 anos e multa, e há regras especiais sobre parentes, concurso e estabelecimento penal federal de segurança máxima.', '["Conduta: solicitar (com promessa ou concessão de vantagem) ou ordenar violência ou grave ameaça contra as pessoas listadas.","Finalidade: impedir, embaraçar ou retaliar processo ou investigação de crimes de organização criminosa, ou a aprovação de medida contra o crime organizado.","Pena: reclusão de 4 a 12 anos e multa.","§1º: também se aplica a condutas contra cônjuge, companheiro, filho ou parente consanguíneo até o terceiro grau, ou por afinidade, das pessoas do caput.","§2º: se a violência ou grave ameaça é tentada ou consumada, aplica-se também a pena do crime correspondente.","§3º: o condenado inicia o cumprimento em estabelecimento penal federal de segurança máxima.","§4º: o preso provisório investigado ou processado é recolhido a estabelecimento penal federal de segurança máxima."]'::jsonb, '["A pena do crime correspondente (violência ou ameaça) se soma à do art. 21-A (§2º).","O regime de cumprimento é em estabelecimento federal de segurança máxima, tanto para condenado quanto para preso provisório.","Atenção às vítimas: agente público, advogado, defensor dativo, jurado, testemunha, colaborador ou perito (e seus familiares até o 3º grau)."]'::jsonb, 'Um chefe de organização promete dinheiro a alguém para ameaçar uma testemunha e impedir seu depoimento. Ele responde pelo art. 21-A e, se a ameaça é consumada, também pelo crime correspondente.', '["Assertiva que exclui a proteção de familiares das pessoas do caput erra: o §1º estende às condutas contra cônjuge, companheiro, filho e parentes até o terceiro grau."]'::jsonb, '[{"termo":"Defensor dativo","significado":"Defensor nomeado pelo juiz para quem não tem advogado."}]'::jsonb, '["Art. 21-B (conspiração)","Art. 2º, §1º (embaraço à investigação)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-21-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crime de conspiração para obstrução de ações contra o crime organizado: duas ou mais pessoas se ajustam para praticar violência ou grave ameaça contra agente público, advogado, defensor dativo, jurado, testemunha, colaborador ou perito, com o fim de impedir, embaraçar ou retaliar investigação ou processo de crimes de organização criminosa, ou a aprovação de medida contra o crime organizado. Pena: reclusão de 4 a 12 anos e multa, com os mesmos parágrafos do art. 21-A.', '["Conduta: ajustarem-se duas ou mais pessoas para a prática de violência ou grave ameaça contra as pessoas listadas.","Finalidade igual à do art. 21-A.","Pena: reclusão de 4 a 12 anos e multa.","§1º a §4º: mesmas regras do art. 21-A (parentes, soma da pena do crime correspondente, estabelecimento federal de segurança máxima para condenado e preso provisório)."]'::jsonb, '["Aqui o crime é o AJUSTE entre duas ou mais pessoas (o número mínimo é duas, diferente das quatro da organização criminosa).","Os parágrafos reproduzem as consequências do art. 21-A."]'::jsonb, 'Dois integrantes combinam ameaçar um jurado para influenciar o julgamento de um chefe da organização. O ajuste já configura o art. 21-B.', '["Assertiva que exige quatro pessoas para a conspiração do art. 21-B confunde com o conceito de organização criminosa: aqui bastam duas."]'::jsonb, '[{"termo":"Conspiração","significado":"Ajuste entre pessoas para praticar o crime, antes da execução."}]'::jsonb, '["Art. 21-A","Art. 1º, §1º (organização com quatro ou mais pessoas)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-21-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes da lei e as infrações conexas seguem o procedimento ordinário do Código de Processo Penal. A instrução criminal deve terminar em prazo razoável, que não pode exceder 120 dias quando o réu estiver preso, prorrogáveis por até igual período, por decisão fundamentada, motivada pela complexidade da causa ou por fato procrastinatório atribuível ao réu.', '["Procedimento: ordinário do Código de Processo Penal.","Instrução em prazo razoável, sem exceder 120 dias se o réu estiver preso.","Prorrogação: até igual período, por decisão fundamentada, por complexidade da causa ou fato procrastinatório do réu."]'::jsonb, '["O prazo de 120 dias vale para réu PRESO e pode ser prorrogado por até igual período (mais 120).","A prorrogação exige decisão fundamentada."]'::jsonb, 'Réu preso em processo complexo: a instrução tem até 120 dias e, por decisão fundamentada, pode ser prorrogada por mais 120.', '["Assertiva que fixa para a instrução do réu preso um prazo diferente de 120 dias troca o prazo legal."]'::jsonb, '[{"termo":"Instrução criminal","significado":"Fase de produção de provas no processo."}]'::jsonb, '["Código de Processo Penal (procedimento ordinário)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz competente pode decretar o sigilo da investigação para garantir a celeridade e a eficácia das diligências, assegurando ao defensor amplo acesso aos elementos de prova que digam respeito ao direito de defesa, precedido de autorização judicial e ressalvadas as diligências em andamento. Antes do depoimento do investigado, o defensor tem direito de vista prévia dos autos, mesmo sigilosos, por no mínimo 3 dias antes do ato.', '["Sigilo decretado pela autoridade judicial competente, para celeridade e eficácia das diligências.","Defensor tem amplo acesso aos elementos ligados à defesa, com autorização judicial, ressalvadas diligências em andamento.","Parágrafo único: determinado o depoimento do investigado, o defensor tem vista prévia dos autos, mesmo sigilosos, em prazo mínimo de 3 dias antes do ato, podendo ser ampliado."]'::jsonb, '["O prazo de vista prévia é de, no mínimo, 3 dias antes do depoimento.","O sigilo não impede o acesso do defensor ao que diz respeito à defesa (exceto diligências em andamento)."]'::jsonb, 'O juiz decreta sigilo da investigação. Marcado o depoimento do investigado, o advogado recebe os autos com pelo menos 3 dias de antecedência.', '["Assertiva que nega ao defensor qualquer acesso aos autos sigilosos erra: o art. 23 assegura acesso aos elementos de defesa."]'::jsonb, '[]'::jsonb, '["Art. 7º, §2º (acesso do defensor no acordo)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 24 não cria regra nova para o estudo da lei: ele altera a redação do art. 288 do Código Penal (hoje ''associação criminosa''), que passou a prever o crime de associação de 3 ou mais pessoas para cometer crimes. A redação do 288 aparece no próprio texto do artigo.', '["Altera o art. 288 do Código Penal (associação criminosa).","Compare: associação criminosa exige 3 ou mais pessoas; organização criminosa exige 4 ou mais, com estrutura e divisão de tarefas."]'::jsonb, '["Muito cobrado: diferença entre 3 pessoas (art. 288 CP) e 4 pessoas (organização criminosa)."]'::jsonb, 'Três amigos se juntam para cometer furtos de forma estável: associação criminosa. Se fossem quatro, com divisão de tarefas e objetivo de vantagem por crimes graves, poderia ser organização criminosa.', '["Assertiva que equipara associação criminosa e organização criminosa quanto ao número de integrantes erra."]'::jsonb, '[]'::jsonb, '["Art. 288 desta lei (texto reproduzido)","Art. 1º, §1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 25 altera o art. 342 do Código Penal (falso testemunho ou falsa perícia), cuja pena passou a ser de reclusão de 2 a 4 anos e multa, como mostra o texto do artigo.', '["Altera o art. 342 do Código Penal; pena de reclusão de 2 a 4 anos e multa."]'::jsonb, '["É uma alteração do Código Penal feita por esta lei: o estudo do tipo completo está no Código Penal."]'::jsonb, 'A testemunha mente em juízo para proteger um chefe da organização: pode responder pelo falso testemunho (art. 342 do CP).', '["Assertiva que atribui ao art. 342 do CP pena diferente da prevista no texto do artigo deve ser conferida com o Código Penal."]'::jsonb, '[]'::jsonb, '["Art. 342 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revoga a Lei 9.034/1995, que tratava das organizações criminosas antes desta lei.', '["Revogação da Lei 9.034/1995."]'::jsonb, '["Artigo de revogação: o estudo prático está nas regras desta lei."]'::jsonb, 'Questões que citam a antiga Lei 9.034/1995 devem ser lidas com atenção à revogação.', '["Assertiva que aplica a Lei 9.034/1995 como vigente erra: ela foi revogada."]'::jsonb, '[]'::jsonb, '["Lei 9.034/1995 (revogada)"]'::jsonb, 'under_review', 'claude'
