insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Define a vigência: a lei entra em vigor 45 dias depois da publicação oficial.', '["Vigência após 45 dias da publicação oficial."]'::jsonb, '["Prazo da vacatio legis: 45 dias."]'::jsonb, 'Contagem do prazo para a lei começar a valer: 45 dias a partir da publicação oficial.', '["Assertiva que fixa vigência imediata na data da publicação troca o prazo."]'::jsonb, '[{"termo":"Vacatio legis","significado":"Período entre a publicação da lei e o início de sua vigência."}]'::jsonb, '[]'::jsonb, 'under_review', 'claude'
