insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É a redação do art. 288 do Código Penal dada por esta lei: o crime de associação criminosa. Configura-se quando 3 ou mais pessoas se associam para o fim específico de cometer crimes. A pena é de reclusão de 1 a 3 anos, aumentada até a metade se a associação é armada ou se há participação de criança ou adolescente.', '["Três ou mais pessoas associadas.","Fim específico de cometer crimes.","Pena: reclusão de 1 a 3 anos.","Aumento de até a metade se a associação é armada ou se há participação de criança ou adolescente."]'::jsonb, '["Associação criminosa (3 ou mais pessoas, sem exigir estrutura ordenada) não se confunde com organização criminosa (4 ou mais, estruturada, divisão de tarefas, vantagem por crimes graves).","O fim específico é cometer crimes: a simples reunião eventual não basta."]'::jsonb, 'Três pessoas se unem de forma estável para praticar furtos. Há associação criminosa. Se uma delas for adolescente, a pena aumenta até a metade.', '["Assertiva que exige quatro pessoas para a associação criminosa do art. 288 troca o número: são três ou mais.","Assertiva que dispensa o fim específico de cometer crimes erra."]'::jsonb, '[{"termo":"Fim específico","significado":"Objetivo determinado que a lei exige além da conduta (aqui, cometer crimes)."}]'::jsonb, '["Art. 1º, §1º (organização criminosa)","Art. 24 desta lei"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'organizacoes' and u.unit_key = 'art-288'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
